if('requestIdleCallback' in window)requestIdleCallback(warmAssets,{timeout:2500});else setTimeout(warmAssets,1200);

document.addEventListener('keydown',e=>{if(s.pendingWork)return;const typing=e.target?.matches?.('input,textarea,select,[contenteditable=true]');if(!typing&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat&&e.key.toLowerCase()==='c'&&!title&&!s.ended&&!['wake','threshold','street','phone'].includes(s.scene)){e.preventDefault();panel=panel==='growth'?null:'growth';render();return;}if(e.key==='Escape'&&panel){panel=null;render();}if(e.key==='Enter'&&e.target?.id==='player-name'){e.preventDefault();root.querySelector('#player-code')?.focus();}else if(e.key==='Enter'&&e.target?.id==='player-code'){e.preventDefault();root.querySelector('[data-a="begin-new"]')?.click();}});

function updateBeam(){const world=root.querySelector('.beam-room .world');if(!world)return;const rect=world.getBoundingClientRect();const r=Math.min(rect.width,rect.height)*(lightSource(s)==='phone'?.32:.52);world.style.setProperty('--beam-x',beam.x+'%');world.style.setProperty('--beam-y',beam.y+'%');world.style.setProperty('--beam-radius',r+'px');world.querySelectorAll('.world-spot').forEach(el=>{const x=parseFloat(el.style.getPropertyValue('--x')),y=parseFloat(el.style.getPropertyValue('--y'));const distance=Math.hypot((x-beam.x)*rect.width/100,(y-beam.y)*rect.height/100);el.classList.toggle('in-beam',distance<r*.76);});}
function pointBeam(e){const world=e.target.closest('.beam-room .world');if(!world)return;const box=world.getBoundingClientRect();beam={x:Math.max(0,Math.min(100,(e.clientX-box.left)/box.width*100)),y:Math.max(0,Math.min(100,(e.clientY-box.top)/box.height*100))};updateBeam();warmWork();}
root.addEventListener('pointerdown',e=>{dragStart={x:e.clientX,y:e.clientY};beamDragged=false;pointBeam(e);});
root.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||e.buttons){if(dragStart&&Math.hypot(e.clientX-dragStart.x,e.clientY-dragStart.y)>12)beamDragged=true;pointBeam(e);}});
window.addEventListener('resize',updateBeam);
root.addEventListener('pointerup',()=>{dragStart=null;setTimeout(()=>{beamDragged=false;},0);});
root.addEventListener('pointercancel',()=>{dragStart=null;beamDragged=false;});


function warmWork(){if(title||s.pendingWork)return;const src=workArt({kind:'shelf',artContext:searchContext(s,'careful','shelf')});warmWork.seen??=new Set();if(warmWork.seen.has(src))return;warmWork.seen.add(src);const img=new Image();img.decoding='async';img.src=src;}
